 *
 * C layout: A[m][n] accessed as A[i][j]
 * Halide layout: Buffer A(n, m) accessed as A(j, i)
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 1> x) {
    Var i("i"), j("j");

    Func init_A("init_A"), init_x("init_x");

    // fn = (DATA_TYPE)n in the original C code
    Expr fn = cast<num_t>(n);

    // x[i] = 1 + (i / fn);
    init_x(i) = cast<num_t>(1) + cast<num_t>(i) / fn;

    // A[i][j] = (DATA_TYPE)((i + j) % n) / (5 * m);
    // Halide: A(j, i) corresponds to C's A[i][j]
    init_A(j, i) = cast<num_t>((i + j) % n) / cast<num_t>(5 * m);

    // Realize into the provided buffers
    init_x.realize(x);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from PolyBench macros)
    int m = M;
    int n = N;

    // Buffers:
    // C: A[M][N] -> Halide: A(n, m), accessed as A(j, i)
    Halide::Buffer<num_t, 2> A(n, m);
    // C: x[N] -> Halide: x(n)
    Halide::Buffer<num_t, 1> x(n);
    // C: y[N] -> Halide: y(n)
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for inputs
    ImageParam A_param(type_of<num_t>(), 2, "A_param");  // (j, i)
    ImageParam x_param(type_of<num_t>(), 1, "x_param");  // (j)

    // Initialize A and x
    init_array(m, n, A, x);

    // Bind buffers to ImageParams
    A_param.set(A);
    x_param.set(x);

    // Vars
    Var i("i"), j("j");

    // Funcs for tmp and y
    Func tmp("tmp"), y_func("y");

    // tmp[i] = sum_j A[i][j] * x[j]
    // In Halide coordinates: tmp(i) = sum over rj of A_param(rj, i) * x_param(rj)
    RDom rj(0, A_param.dim(0).extent(), "rj");  // rj iterates over 0..n-1
    tmp(i) = cast<num_t>(0);
    tmp(i) += A_param(rj, i) * x_param(rj);

    // y[j] = sum_i A[i][j] * tmp[i]
    // In Halide coordinates: y(j) = sum over ri of A_param(j, ri) * tmp(ri)
    RDom ri(0, A_param.dim(1).extent(), "ri");  // ri iterates over 0..m-1
    y_func(j) = cast<num_t>(0);
    y_func(j) += A_param(j, ri) * tmp(ri);

