    Expr denom = cast<num_t>(5 * m);
    init_A(j, i) = cast<num_t>((i + j) % n) / denom;

    init_x.realize(x);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Input and output data (note dimension order per translation rule #1)
    // C: A[m][n] --> Halide: A(n, m) with indexing A(j, i) == A[i][j] in C
    Halide::Buffer<num_t, 2> A(n, m);

    // C: x[n], y[n] --> Halide: x(n), y(n)
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // Initialize A and x
    init_array(m, n, A, x);

