    x_param.set(x);

    // Vars and reduction domains
    Var i("i"), j("j");

    // tmp[i] = sum_j A[i][j] * x[j]
    // In Halide index space:
    //   tmp(i) = sum_{j} A_param(j, i) * x_param(j);
    RDom rj(0, A.dim(0).extent(), "rj");  // iterate over columns j

    Func tmp("tmp");
    tmp(i) = cast<num_t>(0);
    tmp(i) += A_param(rj, i) * x_param(rj);

    // y[j] = sum_i A[i][j] * tmp[i]
    // In Halide index space:
    //   y(j) = sum_{i} A_param(j, i) * tmp(i);
    RDom ri(0, A.dim(1).extent(), "ri");  // iterate over rows i

    Func atax("atax");
    atax(j) = cast<num_t>(0);
    atax(j) += A_param(j, ri) * tmp(ri);

    // Simple schedule:
    // Compute tmp fully at root, then compute y = atax at root.
