    atax.compute_root();

    // Optional reordering of reduction loops to make them explicit.
    atax.update().reorder(j, ri);

    // JIT-compile the pipeline
    atax.compile_jit();

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write results into y buffer
    atax.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
