// include common PolyBench-style definitions (DATA_TYPE, M, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "atax.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A (m x n) and x (length n) with the same values
 * as the original C PolyBench atax.c code.
 *
 * Original C:
 *   fn = (DATA_TYPE)n;
 *   for (i = 0; i < n; i++)
 *       x[i] = 1 + (i / fn);
 *   for (i = 0; i < m; i++)
 *     for (j = 0; j < n; j++)
 *       A[i][j] = ((i + j) % n) / (5 * m);
 *
 * Our Buffers are laid out as:
 *   A(j, i) corresponds to C's A[i][j], with shape (n, m).
 *   x(j)    corresponds to C's x[j],  with shape (n).
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 1> x) {
    Var i("i"), j("j");
    Func init_A("init_A"), init_x("init_x");

    // fn = (DATA_TYPE) n;
    Expr fn = cast<num_t>(n);

    // x[j] = 1 + (j / fn);
    init_x(j) = cast<num_t>(1) + cast<num_t>(j) / fn;

    // A[i][j] = ((i + j) % n) / (5 * m);
    // Remember: A(j, i) == C's A[i][j]
    init_A(j, i) = cast<num_t>((i + j) % n) / cast<num_t>(5 * m);

    init_x.realize(x);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    //   A is m x n in C: A[i][j]
    //   We store as A(j, i) with shape (n, m)
    Halide::Buffer<num_t, 2> A(n, m);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);  // output y[j]

    // Initialize A and x
    init_array(m, n, A, x);

    // Halide params for inputs
    ImageParam A_param(type_of<num_t>(), 2, "A_param");  // (j, i)
    ImageParam x_param(type_of<num_t>(), 1, "x_param");  // (j)

    A_param.set(A);
    x_param.set(x);

    // Vars and reduction domains
    Var i("i"), j("j");

    // tmp[i] = sum_j A[i][j] * x[j]
    // We store tmp(i) where i is the row index.
    Func tmp("tmp");
    RDom rA(0, A_param.dim(0).extent(), "rA");  // iterate over j
    tmp(i) = cast<num_t>(0);
    tmp(i) += A_param(rA, i) * x_param(rA);

    // y[j] = sum_i A[i][j] * tmp[i]
    // We store y_func(j) where j is the column index.
    Func y_func("y");
    RDom rB(0, A_param.dim(1).extent(), "rB");  // iterate over i
    y_func(j) = cast<num_t>(0);
    y_func(j) += A_param(j, rB) * tmp(rB);

    // Simple schedule mirroring a two-phase computation:
    // 1) compute tmp over all rows
    // 2) compute y over all columns
    tmp.compute_root();
    y_func.compute_root();

    // JIT-compile the pipeline
    y_func.compile_jit();

    // Time only the realization (not the compilation)
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute y from A and x
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (to stderr), similar to print_array()
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
