#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, M, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for ATAX
#include "atax.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and x with the same values as the original C version.
 *
 * C code:
 *   fn = (DATA_TYPE)n;
 *   for (i = 0; i < n; i++)
 *       x[i] = 1 + (i / fn);
 *   for (i = 0; i < m; i++)
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
 *
 * Mapping to Halide buffers:
 *   C: A[i][j]  with shape [M][N]
 *   HL: A(j, i) with shape (N, M)  (width = N, height = M)
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 1> x) {
    Var i("i"), j("j");

    Func init_A("init_A"), init_x("init_x");

    // fn = (DATA_TYPE)n;
    Expr fn = cast<num_t>(n);

    // x[i] = 1 + (i / fn);
    init_x(i) = cast<num_t>(1) + cast<num_t>(i) / fn;

    // A[i][j] = ((i + j) % n) / (5 * m);
    Expr denom = cast<num_t>(5 * m);
    init_A(j, i) = cast<num_t>((i + j) % n) / denom;

    // Realize into the provided buffers.
    init_x.realize(x);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A: C has shape [m][n], so Halide uses (n, m) and access as A(j, i).
    Halide::Buffer<num_t, 2> A(n, m);
    // x: length n
    Halide::Buffer<num_t, 1> x(n);
    // y: length n (output)
    Halide::Buffer<num_t, 1> y(n);
    // tmp: length m (intermediate; not directly needed outside the pipeline)
    Halide::Buffer<num_t, 1> tmp(m);

    // Initialize A and x as in the original C code.
    init_array(m, n, A, x);

    // Wrap input arrays as ImageParams for use in the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");  // (n, m)
    ImageParam x_param(type_of<num_t>(), 1, "x_param");  // (n)

    A_param.set(A);
    x_param.set(x);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // RDom over columns (j) and rows (i), using the same extents as the C loops.
    RDom r_col(0, n, "r_col");  // corresponds to j in the C code
    RDom r_row(0, m, "r_row");  // corresponds to i in the C code

    // tmp[i] = sum_j A[i][j] * x[j]
    // y[j]   = sum_i A[i][j] * tmp[i]
    //
    // Mapping:
    //   A[i][j] -> A_param(j, i)
    //   x[j]    -> x_param(j)
    //   tmp[i]  -> tmp_func(i)
    Func tmp_func("tmp"), y_func("y");

    // tmp[i] = 0;
    tmp_func(i) = cast<num_t>(0);
    // for (j = 0; j < n; j++)
    //   tmp[i] += A[i][j] * x[j];
    tmp_func(i) += A_param(r_col, i) * x_param(r_col);

    // y[j] = 0;
    y_func(j) = cast<num_t>(0);
    // for (i = 0; i < m; i++)
    //   y[j] += A[i][j] * tmp[i];
    y_func(j) += A_param(j, r_row) * tmp_func(r_row);

    // --------------------
    // Scheduling
    // --------------------

    // Compute tmp at root: first compute all tmp[i], then use them to compute y.
    tmp_func.compute_root();

    // Compute y at root (final output).
    y_func.compute_root();

    // The default reduction loop order for y_func is:
    //   for (j)
    //     for (r_row)
    //       ...
    // but the original C code loops as:
    //   for (i)
    //     for (j)
    //       y[j] += ...
    //
    // Reorder the update to more closely match the original traversal order:
    //   for (r_row = i)
    //     for (j)
    //       ...
    y_func.update().reorder(r_row, j);

    // JIT-compile the pipeline (this compiles both tmp_func and y_func).
    y_func.compile_jit();

    // Measure execution time of the kernel (realization of y).
    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: compute y into the buffer 'y'.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results (similar spirit to PolyBench's print_array).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; ++idx) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
